import pandas as pd
import io

def generate_excel_bytes(csv_path):
    # Read the CSV generated by your AI
    df = pd.read_csv(csv_path)
    df.columns = [col.replace('_', ' ').title() for col in df.columns]

    # Create an in-memory buffer
    output = io.BytesIO()
    writer = pd.ExcelWriter(output, engine='xlsxwriter')
    df.to_excel(writer, sheet_name='Audit_Trail', index=False)

    workbook  = writer.book
    worksheet = writer.sheets['Audit_Trail']

    # Define Formats
    header_format = workbook.add_format({'bold': True, 'fg_color': '#0f172a', 'font_color': 'white', 'border': 1})
    compliant_format = workbook.add_format({'bg_color': '#dcfce7', 'font_color': '#166534', 'border': 1}) 
    not_found_format = workbook.add_format({'bg_color': '#fee2e2', 'font_color': '#991b1b', 'border': 1})
    standard_format = workbook.add_format({'border': 1, 'text_wrap': True, 'valign': 'top'})

    # Apply Header
    for col_num, value in enumerate(df.columns.values):
        worksheet.write(0, col_num, value, header_format)

    # Apply Row Colors based on "Audit Finding" column
    for row_num in range(1, len(df) + 1):
        finding = str(df.iloc[row_num - 1, 2])
        row_format = compliant_format if finding == 'Compliant' else not_found_format
        
        worksheet.write(row_num, 0, df.iloc[row_num - 1, 0], standard_format)
        worksheet.write(row_num, 1, df.iloc[row_num - 1, 1], standard_format)
        worksheet.write(row_num, 2, finding, row_format)
        worksheet.write(row_num, 3, str(df.iloc[row_num - 1, 3]), standard_format)

    # Set Column Widths
    worksheet.set_column('A:A', 25)
    worksheet.set_column('B:B', 15)
    worksheet.set_column('C:C', 18)
    worksheet.set_column('D:D', 70)

    writer.close()
    return output.getvalue()
